import { resolve } from 'node:path'
import { defineConfig, devices } from '@playwright/test'
import { E2E_SUPABASE_ANON_KEY, E2E_SUPABASE_URL } from './e2e/env'

// E2E builds talk to a made-up Supabase project (every request is served by e2e/fake-supabase.ts).
// Set here so both the preview build (Vite gives process env priority over .env.local) and the
// tests use it: nothing a test does can ever reach the real project.
process.env.VITE_SUPABASE_URL = E2E_SUPABASE_URL
process.env.VITE_SUPABASE_ANON_KEY = E2E_SUPABASE_ANON_KEY

// Generated by e2e/global-setup.ts: a fake camera feed showing a real EAN-13 barcode.
export const BARCODE_VIDEO = resolve('e2e/.generated/barcode.y4m')
export const VIDEO_BARCODE = '3017624010701'

export default defineConfig({
  testDir: './e2e',
  globalSetup: './e2e/global-setup.ts',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  reporter: process.env.CI ? 'github' : 'list',
  use: {
    baseURL: 'http://localhost:4173',
    // Requests made by a service worker bypass page.route (in WebKit), so tests run without one.
    serviceWorkers: 'block',
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'mobile-chrome',
      use: {
        ...devices['Pixel 7'],
        permissions: ['camera'],
        launchOptions: {
          args: [
            '--use-fake-ui-for-media-stream',
            '--use-fake-device-for-media-stream',
            `--use-file-for-fake-video-capture=${BARCODE_VIDEO}`,
          ],
        },
      },
    },
    {
      // Safari's engine at iPhone size. The fake camera feed is Chrome-only, so the real-barcode
      // scan test runs only above; everything else runs on both.
      name: 'mobile-safari',
      use: { ...devices['iPhone 13'] },
      grepInvert: /real barcode with the camera/,
    },
  ],
  webServer: {
    command: 'npm run build && npm run preview -- --port 4173 --strictPort',
    url: 'http://localhost:4173',
    // Always build fresh with the fake project settings above.
    reuseExistingServer: false,
    timeout: 120_000,
  },
})
